actions.script:
resultList = []
for (const productFeature of productFeatureList)
    resultList.push({productFeatureId:productFeature.productFeatureId, label:ec.resource.expand('ProductFeatureNameTemplate', '', productFeature)})

document.parties = Array.from(catalogIndexParties).filter(row => {
    const party = ec.entity.find('mantle.party.Party').condition({partyId:row.partyId}).disableAuthz().one()
    return party && !party.privateOwnerUserId && (party.ownerPartyId === '_NA_' || party.ownerPartyId === document.ownerPartyId || party.partyId === document.ownerPartyId)
}).map(row => ({partyId:row.partyId, otherPartyItemId:row.otherPartyItemId, otherPartyItemName:row.otherPartyItemName}))
